def quantum_security_level(algo, key_size):
    algo = algo.upper()
    if algo in ('RSA', 'DSA', 'ECDSA', 'ECDH'):
        return 0
    elif algo in ('AES', 'SHA-PREIMAGE'):
        return key_size // 2
    elif algo == 'SHA-COLLISION':
        return key_size // 3  # approximation
    else:
        return -1
